<?php
require __DIR__.'/ui.php';role(['admin','gerente','producao']);$p=db();$rows=$p->query("SELECT * FROM products ORDER BY stock<=min_stock DESC,name")->fetchAll();page_head('Estoque');?>
<div class="grid g3"><div class="card kpi"><span>Valor do estoque</span><strong><?=money(array_sum(array_map(fn($x)=>$x['cost']*$x['stock'],$rows)))?></strong></div><div class="card kpi"><span>Itens críticos</span><strong><?=count(array_filter($rows,fn($x)=>$x['stock']<=$x['min_stock']))?></strong></div><div class="card kpi"><span>Itens zerados</span><strong><?=count(array_filter($rows,fn($x)=>$x['stock']<=0))?></strong></div></div>
<div class="card"><div class="table"><table><tr><th>Produto</th><th>Estoque</th><th>Mínimo</th><th>Custo</th><th>Valor</th><th>Status</th></tr><?php foreach($rows as $x):?><tr><td><?=e($x['name'])?></td><td><?=$x['stock']?> <?=e($x['unit'])?></td><td><?=$x['min_stock']?></td><td><?=money($x['cost'])?></td><td><?=money($x['stock']*$x['cost'])?></td><td><span class="badge <?=$x['stock']<=$x['min_stock']?'bad':'ok'?>"><?=$x['stock']<=$x['min_stock']?'Crítico':'OK'?></span></td></tr><?php endforeach;?></table></div></div><?php page_foot();?>